function getHappyString(n, k) {
  const path = [];
  let count = 0;
  let answer = '';

  function backtrack() {
    if (path.length === n) {
      count++;
      if (count === k) {
        answer = path.join('');
      }
      return;
    }
    for (const letter of ['a', 'b', 'c']) {
      if (answer !== '') {
        return;
      }
      if (path.length > 0 && path[path.length - 1] === letter) {
        continue;
      }
      path.push(letter);
      backtrack();
      path.pop();
    }
  }

  backtrack();
  return answer;
}

