function getHappyString(n, k) {
  const happy = [];
  const total = 3 ** n;
  for (let code = 0; code < total; code++) {
    let s = '';
    let value = code;
    for (let p = 0; p < n; p++) {
      s = 'abc'[value % 3] + s;
      value = Math.floor(value / 3);
    }
    let ok = true;
    for (let p = 1; p < n; p++) if (s[p] === s[p - 1]) ok = false;
    if (ok) happy.push(s);
  }
  happy.sort();
  return k <= happy.length ? happy[k - 1] : '';
}

