function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    return [int(7, 10), int(1, 100)];
  }
  const n = int(1, 5);
  const total = 3 * 2 ** (n - 1);
  // Mostly ask for an existing position, sometimes one past the end.
  const k = rand() < 0.75 ? int(1, Math.min(total, 100)) : int(total + 1, Math.max(total + 1, 100));
  return [n, Math.min(k, 100)];
}
